"    // Keep saved token on startup so they don't have to log in again and again
    const token = localStorage.getItem('pos_token');
    if (token) {
      setIsAuthenticated(true);
      // Retrieve username from stored profile if available
      try {
        const profileSaved = localStorage.getItem('pos_profile');
        if (profileSaved) {
          const profileObj = JSON.parse(profileSaved);
          setUsername(profileObj.name || profileObj.username || '');
        }
      } catch (e) {
        console.error("Failed to load cached profile on startup", e);
      }
    } else {
      setIsAuthenticated(false);
    }

    // Timer for initial loading splash screen
    const timer = setTimeout(() => {
      setShowInitialSplash(false);
    }, 2200);
    return () => clearTimeout(timer);
  }, []);"
